mapper.select:
SELECT s.id AS "staffId", s.name AS "staffName", COALESCE(sp.name, s.position) AS "positionName", s.profile_image_url AS "profileImageUrl", COUNT(r.id) AS "reservationCount", COUNT(CASE WHEN r.status = 'COMPLETED' THEN 1 END) AS "completedCount", COUNT(CASE WHEN r.status = 'CANCELLED' THEN 1 END) AS "cancelledCount", COUNT(CASE WHEN r.status = 'NO_SHOW' THEN 1 END) AS "noShowCount", COALESCE(SUM(CASE WHEN r.status = 'COMPLETED' THEN r.total_price ELSE 0 END), 0) AS "totalRevenue", COALESCE(AVG(CASE WHEN r.status = 'COMPLETED' THEN r.total_price END), 0)::bigint AS "averageRevenue", COALESCE(AVG(CASE WHEN r.status = 'COMPLETED' THEN r.total_duration END), 0)::integer AS "averageDuration", ROUND( COUNT(CASE WHEN r.status = 'COMPLETED' THEN 1 END) * 100.0 / NULLIF(COUNT(r.id), 0), 1 ) AS "completionRate", COUNT(DISTINCT r.customer_id) AS "customerCount" FROM staffs s LEFT JOIN staff_positions sp ON s.position_id = sp.id LEFT JOIN reservations r ON s.id = r.staff_id AND r.business_id = #{businessId} AND r.reservation_date BETWEEN #{startDate} AND #{endDate} WHERE s.business_id = #{businessId} AND s.is_active = 'Y'
AND s.id = #{staffId}
GROUP BY s.id, s.name, sp.name, s.position, s.profile_image_url ORDER BY "totalRevenue" DESC

SELECT s.id AS "staffId", s.name AS "staffName", TO_CHAR(r.reservation_date, 'YYYY-MM') AS "date", COALESCE(SUM(CASE WHEN r.status = 'COMPLETED' THEN r.total_price ELSE 0 END), 0) AS "revenue", COUNT(r.id) AS "reservationCount" FROM staffs s LEFT JOIN reservations r ON s.id = r.staff_id AND r.business_id = #{businessId} AND r.reservation_date BETWEEN #{startDate} AND #{endDate} WHERE s.business_id = #{businessId} AND s.is_active = 'Y'
AND s.id = #{staffId}
GROUP BY s.id, s.name, TO_CHAR(r.reservation_date, 'YYYY-MM') ORDER BY s.id, "date" ASC

WITH service_data AS ( SELECT (jsonb_array_elements(r.services)->>'id')::bigint AS service_id, jsonb_array_elements(r.services)->>'name' AS service_name, (jsonb_array_elements(r.services)->>'price')::integer AS service_price, (jsonb_array_elements(r.services)->>'duration')::integer AS service_duration, r.status FROM reservations r WHERE r.business_id = #{businessId} AND r.reservation_date BETWEEN #{startDate} AND #{endDate} AND r.services IS NOT NULL ), total AS ( SELECT COALESCE(SUM(service_price), 1) AS total_revenue FROM service_data WHERE status = 'COMPLETED' ), ranked AS ( SELECT sd.service_id, sd.service_name, s.category_id, sc.name AS category_name, COUNT(*) AS reservation_count, COALESCE(SUM(CASE WHEN sd.status = 'COMPLETED' THEN sd.service_price ELSE 0 END), 0) AS total_revenue, COALESCE(AVG(sd.service_price), 0)::bigint AS average_price, ROUND( SUM(CASE WHEN sd.status = 'COMPLETED' THEN sd.service_price ELSE 0 END) * 100.0 / t.total_revenue, 1 ) AS revenue_percentage, COALESCE(AVG(sd.service_duration), 0)::integer AS average_duration, ROUND( COUNT(CASE WHEN sd.status = 'COMPLETED' THEN 1 END) * 100.0 / NULLIF(COUNT(*), 0), 1 ) AS completion_rate, ROW_NUMBER() OVER (ORDER BY SUM(CASE WHEN sd.status = 'COMPLETED' THEN sd.service_price ELSE 0 END) DESC) AS rn FROM service_data sd LEFT JOIN services s ON sd.service_id = s.id LEFT JOIN service_categories sc ON s.category_id = sc.id CROSS JOIN total t WHERE 1=1
AND s.category_id = #{categoryId}
GROUP BY sd.service_id, sd.service_name, s.category_id, sc.name, t.total_revenue ) SELECT rn::integer AS "rank", service_id AS "serviceId", service_name AS "serviceName", category_id AS "categoryId", category_name AS "categoryName", reservation_count AS "reservationCount", total_revenue AS "totalRevenue", average_price AS "averagePrice", revenue_percentage AS "revenuePercentage", average_duration AS "averageDuration", completion_rate AS "completionRate" FROM ranked ORDER BY rn LIMIT 20
